    42	static int crt_reinit(gnutls_x509_crt_t crt)
    43	{
    44	        int result;
    45	
    46	        _gnutls_free_datum(&crt->der);
    47	        crt->raw_dn.size = 0;
    48	        crt->raw_issuer_dn.size = 0;
