    79	/**
    80	 * gnutls_x509_crt_equals - This function compares two gnutls_x509_crt_t certificates
    81	 * @cert1: The first certificate
    82	 * @cert2: The second certificate
    83	 *
    84	 * This function will compare two X.509 certificate structures.
    85	 *
    86	 * Returns: On equality non-zero is returned, otherwise zero.
    87	 *
    88	 * Since: 3.5.0
    89	 **/
    90	unsigned gnutls_x509_crt_equals(gnutls_x509_crt_t cert1,
    91	                                gnutls_x509_crt_t cert2)
    92	{
    93	        int ret;
    94	        bool result;
    95	
    96	        if (cert1->modified == 0 && cert2->modified == 0 &&
    97	            cert1->raw_dn.size > 0 && cert2->raw_dn.size > 0) {
    98	                ret = _gnutls_is_same_dn(cert1, cert2);
    99	                if (ret == 0)
   100	                        return 0;
   101	        }
   102	
   103	        if (cert1->der.size == 0 || cert2->der.size == 0 ||
   104	            cert1->modified != 0 || cert2->modified != 0) {
   105	                gnutls_datum_t tmp1, tmp2;
   106	
   107	                /* on uninitialized or modified certificates, we have to re-encode */
   108	                ret =
   109	                    gnutls_x509_crt_export2(cert1, GNUTLS_X509_FMT_DER, &tmp1);
   110	                if (ret < 0)
   111	                        return gnutls_assert_val(0);
   112	
   113	                ret =
   114	                    gnutls_x509_crt_export2(cert2, GNUTLS_X509_FMT_DER, &tmp2);
   115	                if (ret < 0) {
   116	                        gnutls_free(tmp1.data);
   117	                        return gnutls_assert_val(0);
   118	                }
   119	
   120	                if ((tmp1.size == tmp2.size) &&
   121	                    (memcmp(tmp1.data, tmp2.data, tmp1.size) == 0))
   122	                        result = 1;
   123	                else
   124	                        result = 0;
   125	
   126	                gnutls_free(tmp1.data);
   127	                gnutls_free(tmp2.data);
   128	        } else {
   129	                if ((cert1->der.size == cert2->der.size) &&
   130	                    (memcmp(cert1->der.data, cert2->der.data, cert1->der.size) == 0))
   131	                        result = 1;
   132	                else
   133	                        result = 0;
   134	        }
   135	
   136	        return result;
   137	}
