   185	/**
   186	 * gnutls_x509_crt_init:
   187	 * @cert: A pointer to the type to be initialized
   188	 *
   189	 * This function will initialize an X.509 certificate structure.
   190	 *
   191	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   192	 *   negative error value.
   193	 **/
   194	int gnutls_x509_crt_init(gnutls_x509_crt_t * cert)
   195	{
   196	        gnutls_x509_crt_t tmp;
   197	        int result;
   198	
   199	        FAIL_IF_LIB_ERROR;
   200	
   201	        tmp =
   202	            gnutls_calloc(1, sizeof(gnutls_x509_crt_int));
   203	
   204	        if (!tmp)
   205	                return GNUTLS_E_MEMORY_ERROR;
   206	
   207	        result = asn1_create_element(_gnutls_get_pkix(),
   208	                                     "PKIX1.Certificate", &tmp->cert);
   209	        if (result != ASN1_SUCCESS) {
   210	                gnutls_assert();
   211	                gnutls_free(tmp);
   212	                return _gnutls_asn2err(result);
   213	        }
   214	
   215	        result = gnutls_subject_alt_names_init(&tmp->san);
   216	        if (result < 0) {
   217	                gnutls_assert();
   218	                asn1_delete_structure(&tmp->cert);
   219	                gnutls_free(tmp);
   220	                return result;
   221	        }
   222	
   223	        result = gnutls_subject_alt_names_init(&tmp->ian);
   224	        if (result < 0) {
   225	                gnutls_assert();
   226	                asn1_delete_structure(&tmp->cert);
   227	                gnutls_free(tmp);
   228	                gnutls_subject_alt_names_deinit(tmp->san);
   229	                return result;
   230	        }
   231	
   232	        /* If you add anything here, be sure to check if it has to be added
   233	           to gnutls_x509_crt_import as well. */
   234	
   235	        *cert = tmp;
   236	
   237	        return 0;               /* success */
   238	}
