   249	 *   negative error value.
   250	 -*/
   251	int _gnutls_x509_crt_cpy(gnutls_x509_crt_t dest, gnutls_x509_crt_t src)
   252	{
   253	        int ret;
   254	        gnutls_datum_t tmp;
   255	        unsigned dealloc = 0;
   256	
   257	        if (src->der.size == 0 || src->modified) {
   258	                ret =
   259	                    gnutls_x509_crt_export2(src, GNUTLS_X509_FMT_DER, &tmp);
   260	                if (ret < 0)
   261	                        return gnutls_assert_val(ret);
   262	                dealloc = 1;
   263	        } else {
   264	                tmp.data = src->der.data;
   265	                tmp.size = src->der.size;
   266	        }
   267	
   268	        ret = gnutls_x509_crt_import(dest, &tmp, GNUTLS_X509_FMT_DER);
   269	
   270	        if (dealloc) {
   271	                gnutls_free(tmp.data);
   272	        }
   273	
   274	        if (ret < 0)
   275	                return gnutls_assert_val(ret);
   276	
   277	        return 0;
   278	}
