   299	static int compare_sig_algorithm(gnutls_x509_crt_t cert)
   300	{
   301	        int ret, len1, len2, result;
   302	        char oid1[MAX_OID_SIZE];
   303	        char oid2[MAX_OID_SIZE];
   304	        gnutls_datum_t sp1 = {NULL, 0};
   305	        gnutls_datum_t sp2 = {NULL, 0};
   306	        unsigned empty1 = 0, empty2 = 0;
   307	
   308	        len1 = sizeof(oid1);
   309	        result = asn1_read_value(cert->cert, "signatureAlgorithm.algorithm", oid1, &len1);
   310	        if (result != ASN1_SUCCESS) {
   311	                gnutls_assert();
   312	                return _gnutls_asn2err(result);
   313	        }
   314	
   315	        len2 = sizeof(oid2);
   316	        result = asn1_read_value(cert->cert, "tbsCertificate.signature.algorithm", oid2, &len2);
   317	        if (result != ASN1_SUCCESS) {
   318	                gnutls_assert();
   319	                return _gnutls_asn2err(result);
   320	        }
   321	
   322	        if (len1 != len2 || memcmp(oid1, oid2, len1) != 0) {
   323	                _gnutls_debug_log("signatureAlgorithm.algorithm differs from tbsCertificate.signature.algorithm: %s, %s\n",
   324	                        oid1, oid2);
   325	                gnutls_assert();
   326	                return GNUTLS_E_CERTIFICATE_ERROR;
   327	        }
   328	
   329	        /* compare the parameters */
   330	        ret = _gnutls_x509_read_value(cert->cert, "signatureAlgorithm.parameters", &sp1);
   331	        if (ret == GNUTLS_E_ASN1_ELEMENT_NOT_FOUND) {
   332	                empty1 = 1;
   333	        } else if (ret < 0) {
   334	                gnutls_assert();
   335	                return ret;
   336	        }
   337	
   338	        ret = _gnutls_x509_read_value(cert->cert, "signatureAlgorithm.parameters", &sp2);
   339	        if (ret == GNUTLS_E_ASN1_ELEMENT_NOT_FOUND) {
   340	                empty2 = 1;
   341	        } else if (ret < 0) {
   342	                gnutls_assert();
   343	                return ret;
   344	        }
   345	
   346	        /* handle equally empty parameters with missing parameters */
   347	        if (sp1.size == 2 && memcmp(sp1.data, "\x05\x00", 2) == 0) {
   348	                empty1 = 1;
   349	                _gnutls_free_datum(&sp1);
   350	        }
   351	
   352	        if (sp2.size == 2 && memcmp(sp2.data, "\x05\x00", 2) == 0) {
   353	                empty2 = 1;
   354	                _gnutls_free_datum(&sp2);
   355	        }
   356	
   357	        if (empty1 != empty2 || 
   358	            sp1.size != sp2.size || safe_memcmp(sp1.data, sp2.data, sp1.size) != 0) {
   359	                gnutls_assert();
   360	                ret = GNUTLS_E_CERTIFICATE_ERROR;
   361	                goto cleanup;
   362	        }
   363	
   364	        ret = 0;
   365	 cleanup:
   366	        _gnutls_free_datum(&sp1);
   367	        _gnutls_free_datum(&sp2);
   368	        return ret;
   369	}
