   371	static int cache_alt_names(gnutls_x509_crt_t cert)
   372	{
   373	        gnutls_datum_t tmpder = {NULL, 0};
   374	        int ret;
   375	
   376	        /* pre-parse subject alt name */
   377	        ret = _gnutls_x509_crt_get_extension(cert, "2.5.29.17", 0, &tmpder, NULL);
   378	        if (ret < 0 && ret != GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
   379	                gnutls_free(tmpder.data);
   380	                return gnutls_assert_val(ret);
   381	        }
   382	
   383	        if (ret >= 0) {
   384	                ret = gnutls_x509_ext_import_subject_alt_names(&tmpder, cert->san, 0);
   385	                gnutls_free(tmpder.data);
   386	                tmpder.data = NULL;
   387	                if (ret < 0)
   388	                        return gnutls_assert_val(ret);
   389	        }
   390	
   391	        ret = _gnutls_x509_crt_get_extension(cert, "2.5.29.18", 0, &tmpder, NULL);
   392	        if (ret < 0 && ret != GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE)
   393	                return gnutls_assert_val(ret);
   394	
   395	        if (ret >= 0) {
   396	                ret = gnutls_x509_ext_import_subject_alt_names(&tmpder, cert->ian, 0);
   397	                gnutls_free(tmpder.data);
   398	                if (ret < 0)
   399	                        return gnutls_assert_val(ret);
   400	        }
   401	
   402	        return 0;
   403	}
